// Some portions generated by Claude
// @ts-check
const { test, expect } = require('@playwright/test');
const {
    createSeededRepository,
    deleteRepository,
    evidencePath,
    evidenceScreenshots,
    repositoryPageUrl,
    serverBaseUrl,
    uniqueRepositoryId,
    waitForRoute
} = require('./workbench-test-helpers.js');

// The Graph page's React island reuses the Workbench design system: its background, text and font come from the
// --workbench-* tokens, it follows the light/dark switch, and it fills the window: no footer, no page scroll.
const REPOSITORY_ID = uniqueRepositoryId('graph-visual');
const EVIDENCE_DIR = process.env.E2E_GRAPH_EXPLORER_EVIDENCE_DIR || '';

test.beforeAll(async ({ request }) => {
    await createSeededRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

test.afterAll(async ({ request }) => {
    await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

async function openGraphPage(page, width, height) {
    await page.setViewportSize({ width, height });
    await page.goto(repositoryPageUrl(REPOSITORY_ID, 'graph'));
    await waitForRoute(page, 'graph');
    await page.locator('.graph-explorer').getByRole('button', { name: 'Load 100 statements' }).click();
    await page.locator('.graph-explorer .graph-node').first().waitFor({ state: 'attached', timeout: 30000 });
}

async function islandColours(page) {
    return page.evaluate(() => {
        const island = document.querySelector('.graph-explorer');
        const root = getComputedStyle(document.documentElement);
        const style = getComputedStyle(island);
        const probe = document.createElement('div');
        probe.style.background = root.getPropertyValue('--workbench-canvas').trim();
        probe.style.color = root.getPropertyValue('--workbench-ink').trim();
        document.body.appendChild(probe);
        const expected = { background: getComputedStyle(probe).backgroundColor, ink: getComputedStyle(probe).color,
            font: getComputedStyle(document.body).fontFamily };
        probe.remove();
        return {
            background: style.backgroundColor,
            ink: style.color,
            font: style.fontFamily,
            workbenchFont: root.getPropertyValue('--workbench-font').trim(),
            expected,
            scrollWidth: document.documentElement.scrollWidth,
            innerWidth: window.innerWidth,
            scrollHeight: document.documentElement.scrollHeight,
            innerHeight: window.innerHeight,
            footer: getComputedStyle(document.getElementById('footer')).display,
            topbar: document.querySelectorAll('.graph-explorer .topbar').length,
            fullBleed: document.getElementById('workbench-page-surface').classList.contains('workbench-page-surface--full-bleed')
        };
    });
}

// The toolbar shows its button labels while everything fits on one row with them, then only their icons, and only then
// its narrow layout (the views on a row of their own, the actions spread below): it never wraps on its own.
test('the graph explorer waits for its stylesheet across route disposal and remount', async ({ page }) => {
    let releaseStylesheet;
    let stylesheetRequested;
    const stylesheetGate = new Promise((resolve) => { releaseStylesheet = resolve; });
    const requestStarted = new Promise((resolve) => { stylesheetRequested = resolve; });
    let stylesheetRequests = 0;
    await page.route((url) => new URL(url).pathname.endsWith('/styles/graph-explorer.css'), async (route) => {
        const response = await route.fetch();
        if (++stylesheetRequests === 1) {
            stylesheetRequested();
        }
        await stylesheetGate;
        await route.fulfill({ response });
    });

    const graphUrl = repositoryPageUrl(REPOSITORY_ID, 'graph');
    const summaryUrl = repositoryPageUrl(REPOSITORY_ID, 'summary');
    try {
        await page.setViewportSize({ width: 1700, height: 900 });
        await page.goto(summaryUrl, { waitUntil: 'domcontentloaded' });
        await waitForRoute(page, 'summary');
        expect(stylesheetRequests, 'unrelated routes do not load graph styles').toBe(0);

        await page.evaluate((url) => window.workbench.router.navigate(url, { history: 'push' }), graphUrl);
        await waitForRoute(page, 'graph');
        await requestStarted;
        await expect(page.locator('.graph-explorer .graph-toolbar')).toHaveCount(0);

        await page.evaluate((url) => window.workbench.router.navigate(url, { history: 'push' }), summaryUrl);
        await waitForRoute(page, 'summary');
        await expect(page.locator('.graph-explorer .graph-toolbar')).toHaveCount(0);

        await page.evaluate((url) => window.workbench.router.navigate(url, { history: 'push' }), graphUrl);
        await waitForRoute(page, 'graph');
        await expect(page.locator('.graph-explorer .graph-toolbar')).toHaveCount(0);
    } finally {
        releaseStylesheet();
    }

    const toolbar = page.locator('.graph-explorer .graph-toolbar');
    await expect(toolbar).toBeVisible();
    await expect(toolbar).toHaveAttribute('data-fit', 'labels');
    await expect.poll(() => toolbar.evaluate((bar) => {
        const tops = [...bar.children].map((item) => Math.round(item.getBoundingClientRect().top));
        return new Set(tops).size;
    })).toBe(1);
    await expect(page.locator('.graph-explorer .toolbar-label').first()).toBeVisible();
    await expect(page.locator('.graph-explorer')).toHaveCount(1);
    expect(stylesheetRequests, 'the pending document stylesheet is reused on remount').toBe(1);
});

test('a failed graph stylesheet load reports an accessible retry and recovers', async ({ page }) => {
    let stylesheetRequests = 0;
    await page.route((url) => new URL(url).pathname.endsWith('/styles/graph-explorer.css'), async (route) => {
        if (++stylesheetRequests === 1) {
            await route.fulfill({ status: 503, contentType: 'text/plain', body: 'stylesheet unavailable' });
        } else {
            await route.continue();
        }
    });

    await page.setViewportSize({ width: 1700, height: 900 });
    await page.goto(repositoryPageUrl(REPOSITORY_ID, 'graph'), { waitUntil: 'domcontentloaded' });
    await waitForRoute(page, 'graph');
    const alert = page.getByRole('alert');
    await expect(alert).toContainText('The graph explorer could not be loaded.');
    await alert.getByRole('button', { name: /retry/i }).click();
    const toolbar = page.locator('.graph-explorer .graph-toolbar');
    await expect(toolbar).toBeVisible();
    await expect(toolbar).toHaveAttribute('data-fit', 'labels');
    await expect(page.locator('.graph-explorer .toolbar-label').first()).toBeVisible();
    await expect(page.locator('.graph-explorer')).toHaveCount(1);
    expect(stylesheetRequests).toBe(2);
});

test('the toolbar is one bar at every width: labels, then icons, then its compact form', async ({ page }) => {
    const errors = [];
    page.on('pageerror', (error) => errors.push(error.message));
    page.on('console', (message) => message.type() === 'error' && errors.push(message.text()));
    await openGraphPage(page, 1700, 900);
    const toolbar = page.locator('.graph-explorer .graph-toolbar');
    const state = () => toolbar.evaluate((bar) => {
        const items = [...bar.querySelectorAll(':scope > *, .toolbar-actions > *')]
            .filter((item) => !item.matches('.toolbar-actions') && getComputedStyle(item).display !== 'none');
        const tops = items.map((item) => Math.round(item.getBoundingClientRect().top + item.getBoundingClientRect().height / 2));
        return {
            fit: bar.dataset.fit,
            rows: Math.max(...tops) - Math.min(...tops) <= 4 ? 1 : 2,
            labels: getComputedStyle(bar.querySelector('.toolbar-label')).display !== 'none',
            overflow: bar.scrollWidth > bar.clientWidth + 1,
        };
    });
    const seen = [];
    // Down to the narrowest phones (320px), where the compact form still fits on one row.
    for (const width of [1700, 1460, 1300, 1100, 1000, 900, 800, 700, 600, 480, 390, 360, 320, 1000, 1700]) {
        await page.setViewportSize({ width, height: 900 });
        await expect.poll(async () => (await state()).rows, { message: `one row at ${width}px` }).toBe(1);
        seen.push({ width, ...(await state()) });
    }
    expect(seen.every((entry) => !entry.overflow), JSON.stringify(seen)).toBe(true);
    expect(seen[0].labels, 'labels when there is room').toBe(true);
    expect(seen.some((entry) => entry.fit === 'icons'), 'icons before anything else').toBe(true);
    expect(seen.find((entry) => entry.width === 390).fit, 'the compact form on a phone').toBe('compact');
    await expect.poll(async () => (await state()).labels, { message: 'labels again once there is room' }).toBe(true);
    expect(errors.filter((message) => /ResizeObserver/.test(message))).toEqual([]);
});

test('the views are chosen from one View menu named after the current view', async ({ page }) => {
    await openGraphPage(page, 1024, 768);
    const explorer = page.locator('.graph-explorer');
    await expect(explorer.getByRole('tab')).toHaveCount(0);
    const views = explorer.locator('.view-menu > summary');
    await expect(views).toHaveText('Graph');
    await expect(views).toHaveAccessibleName('View: Graph');

    await views.click();
    const choices = explorer.locator('.view-menu-popover button');
    await expect(choices).toHaveCount(7);
    await expect(choices.filter({ hasText: 'Graph' }).first()).toHaveAttribute('aria-current', 'true');
    await explorer.locator('.view-menu-popover button[data-view="table"]').click();

    await expect(views).toHaveText('Triples');
    await expect(explorer.locator('.view-menu')).not.toHaveAttribute('open', '');
});

test('on a phone the toolbar keeps every action: undo, redo, values, labels and full screen move into Tools', async ({ page }) => {
    await openGraphPage(page, 390, 844);
    const explorer = page.locator('.graph-explorer');
    await expect(explorer.locator('.graph-toolbar')).toHaveAttribute('data-fit', 'compact');
    await expect(explorer.getByRole('button', { name: 'Undo the last graph change' })).toBeHidden();
    await expect(explorer.getByRole('button', { name: 'Show values and types as nodes' })).toBeHidden();
    await expect(explorer.getByRole('button', { name: 'Enter full screen' })).toBeHidden();

    await explorer.getByLabel('Open workspace tools').click();
    const tools = explorer.locator('.toolbar-menu-popover');
    for (const name of ['Undo', 'Redo', 'Show values and types as nodes', 'Show all relation labels', 'Full screen']) {
        await expect(tools.getByRole('button', { name, exact: true })).toBeVisible();
    }
    await tools.getByRole('button', { name: 'Show values and types as nodes', exact: true }).click();
    await explorer.getByLabel('Open workspace tools').click();
    await expect(tools.getByRole('button', { name: 'Show values and types as nodes', exact: true }))
        .toHaveAttribute('aria-pressed', 'true');
});

for (const theme of ['light', 'dark']) {
    test(`the graph explorer takes its surface, ink and font from the Workbench (${theme})`, async ({ page }) => {
        await page.addInitScript((preference) => localStorage.setItem('rdf4j-workbench-theme', preference), theme);
        await openGraphPage(page, 1440, 900);
        await expect(page.locator('html')).toHaveAttribute('data-theme', theme);

        const colours = await islandColours(page);
        expect(colours.background).toBe(colours.expected.background);
        expect(colours.ink).toBe(colours.expected.ink);
        expect(colours.font).toBe(colours.expected.font);
        expect(colours.topbar).toBe(0);
        expect(colours.fullBleed).toBe(true);
        expect(colours.scrollWidth).toBeLessThanOrEqual(colours.innerWidth);
        expect(colours.scrollHeight).toBeLessThanOrEqual(colours.innerHeight);
        expect(colours.footer).toBe('none');
        if (evidenceScreenshots()) {
            await page.screenshot({ path: evidencePath(EVIDENCE_DIR, `graph-explorer-${theme}-1440.png`), fullPage: false });
        }
    });
}

for (const [width, height] of [[1024, 768], [390, 844]]) {
    test(`the graph explorer fills the window at ${width}px without scrolling it either way`, async ({ page }) => {
        await openGraphPage(page, width, height);
        const colours = await islandColours(page);
        expect(colours.scrollWidth).toBeLessThanOrEqual(colours.innerWidth);
        expect(colours.scrollHeight).toBeLessThanOrEqual(colours.innerHeight);
        expect(colours.footer).toBe('none');
        if (evidenceScreenshots()) {
            await page.screenshot({ path: evidencePath(EVIDENCE_DIR, `graph-explorer-light-${width}.png`), fullPage: false });
        }
    });
}
